using System.Security.Cryptography.X509Certificates;
using System.Text.Json;
using PortableDocument.Core;
using PortableDocument.Document;
using Xunit;

namespace FreeDF.Tests;

/// <summary>
/// Reads PAdES files produced by pyHanko 0.38.0 (tests/fixtures/signatures/pades, regenerated by generate_pades_fixtures.py): B-B, B-LT (signature timestamp + DSS)
/// and B-LTA (plus archive document timestamp), checking trust, revocation and validation-time handling against an independent implementation.
/// The tests use the checked-in root and a fixed validation instant, so they do not depend on the current date or on Python.
/// </summary>
public class PadesInteropTests
{
    static string Path_(string name) => Path.Combine(AppContext.BaseDirectory, "fixtures", "signatures", "pades", name);
    static byte[] Fx(string name) => File.ReadAllBytes(Path_(name));

    static (X509Certificate2 Root, DateTimeOffset Generated, DateTimeOffset RevokedAt) Setup()
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(Path_("manifest.json")));
        var root = doc.RootElement;
        return (X509CertificateLoader.LoadCertificate(Fx("root.cer")),
            DateTimeOffset.Parse(root.GetProperty("generated").GetString()!), DateTimeOffset.Parse(root.GetProperty("revoked_after_signing").GetString()!));
    }

    [Fact]
    public void Pades_b_b_is_intact_but_only_valid_when_revocation_is_not_required()
    {
        var (root, gen, _) = Setup();
        var pdf = Fx("pyhanko-pades-b-b.pdf");
        var s = Assert.Single(PdfEditor.VerifySignatures(pdf));
        Assert.Equal("ETSI.CAdES.detached", s.SubFilter);
        Assert.True(s.IsIntact, s.Error);
        Assert.True(s.SigningCertificateV2Valid);
        var strict = Assert.Single(PdfSignatureTrust.Evaluate(pdf, new PdfTrustPolicy { TrustAnchors = [root], ValidationTime = gen.AddMinutes(1) }));
        Assert.Equal(PdfTrustStatus.Indeterminate, strict.Trust.Status);
        var lax = Assert.Single(PdfSignatureTrust.Evaluate(pdf, new PdfTrustPolicy { TrustAnchors = [root], ValidationTime = gen.AddMinutes(1), Revocation = PdfRevocationRequirement.Ignore }));
        Assert.Equal(PdfTrustStatus.Valid, lax.Trust.Status);
    }

    [Fact]
    public void Pades_b_lt_validates_from_dss_at_the_signature_timestamp_time()
    {
        var (root, gen, _) = Setup();
        var pdf = Fx("pyhanko-pades-b-lt.pdf");
        var dss = PdfEditor.ReadDocumentSecurityStore(pdf);
        Assert.NotNull(dss);
        var sig = Assert.Single(PdfEditor.VerifySignatures(pdf));
        Assert.True(sig.IsIntact && sig.HasValidationInformation, sig.Error);
        var r = Assert.Single(PdfSignatureTrust.Evaluate(pdf, new PdfTrustPolicy { TrustAnchors = [root] })).Trust;
        Assert.Equal(PdfTrustStatus.Valid, r.Status);
        Assert.Equal(PdfValidationTimeSource.DocumentTimestamp, r.ValidationTimeSource);
        Assert.InRange(r.ValidationTime, gen.AddMinutes(-1), gen.AddMinutes(10));
        Assert.Contains(r.Revocation, x => x.Outcome == PdfRevocationOutcome.Good && x.Source.EndsWith("/DSS"));
        // Without the DSS there is no evidence, so the same file is only Indeterminate.
        var noDss = Assert.Single(PdfSignatureTrust.Evaluate(pdf, new PdfTrustPolicy { TrustAnchors = [root], UseEmbeddedValidationData = false })).Trust;
        Assert.Equal(PdfTrustStatus.Indeterminate, noDss.Status);
    }

    [Fact]
    public void Pades_b_lta_has_signature_and_archive_timestamp_that_both_validate()
    {
        var (root, gen, _) = Setup();
        var pdf = Fx("pyhanko-pades-b-lta.pdf");
        var results = PdfSignatureTrust.Evaluate(pdf, new PdfTrustPolicy { TrustAnchors = [root], ValidationTime = gen.AddMinutes(1) });
        Assert.True(results.Count >= 2);
        Assert.False(results[0].Signature.IsDocumentTimeStamp);
        Assert.All(results.Where(x => x.Signature.IsDocumentTimeStamp), x => Assert.True(x.Signature.IsIntact, x.Signature.Error));
        Assert.Equal(PdfTrustStatus.Valid, results[0].Trust.Status);
        Assert.Contains(results, x => x.Signature.IsDocumentTimeStamp);
        var lt = Assert.Single(PdfSignatureTrust.Evaluate(pdf, new PdfTrustPolicy { TrustAnchors = [root] }).Take(1)).Trust;
        Assert.Equal(PdfValidationTimeSource.DocumentTimestamp, lt.ValidationTimeSource);
        Assert.Equal(PdfTrustStatus.Valid, lt.Status);
    }

    [Fact]
    public void Revocation_after_signing_does_not_invalidate_but_revocation_before_validation_does()
    {
        var (root, gen, revokedAt) = Setup();
        var pdf = Fx("pyhanko-pades-revoked.pdf");
        var data = new PdfValidationData();
        data.Crls.Add(Fx("pyhanko-pades-revoked.crl"));
        var atSigning = Assert.Single(PdfSignatureTrust.Evaluate(pdf, new PdfTrustPolicy { TrustAnchors = [root], SuppliedData = data })).Trust;
        Assert.Equal(PdfValidationTimeSource.DocumentTimestamp, atSigning.ValidationTimeSource);
        Assert.Equal(PdfTrustStatus.Valid, atSigning.Status);
        var later = Assert.Single(PdfSignatureTrust.Evaluate(pdf, new PdfTrustPolicy { TrustAnchors = [root], SuppliedData = data, ValidationTime = revokedAt.AddMinutes(5), UseDocumentTimestamps = false })).Trust;
        Assert.Equal(PdfTrustStatus.Invalid, later.Status);
        Assert.Contains(later.Findings, f => f.Code == "Revoked");
    }

    [Fact]
    public void Library_adds_dss_to_a_pyhanko_signature_in_a_way_pyhanko_files_can_be_extended()
    {
        var (root, gen, _) = Setup();
        var pdf = Fx("pyhanko-pades-b-b.pdf");
        var data = new PdfValidationData();
        data.Crls.Add(Fx("pyhanko-pades-revoked.crl"));
        var ltv = PdfEditor.AddValidationInformation(pdf, data);
        var s = Assert.Single(PdfEditor.VerifySignatures(ltv));
        Assert.True(s.IsIntact && s.HasValidationInformation);
        Assert.Equal(1, PdfEditor.ReadDocumentSecurityStore(ltv)!.Crls);
    }
}
